import{c as a,S as t,j as o,m as s}from"./chunks/framework.C68YPdek.js";const m=JSON.parse('{"title":"Backend","description":"","frontmatter":{},"headers":[],"relativePath":"developer/architecture/backend.md","filePath":"developer/architecture/backend.md"}'),r={name:"developer/architecture/backend.md"};function n(d,e,c,i,h,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to “Backend”">​</a></h1><p><a href="https://github.com/source-academy/backend" target="_blank" rel="noreferrer"><code>backend</code></a> (the application is called <strong>Cadet</strong>) is the server of Source Academy @ NUS and of any deployment that has accounts, courses and assessments. Elixir, Phoenix and PostgreSQL; Ecto for the database and Oban for background jobs. Checked against the repository on 28 November 2026.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to “What it does”">​</a></h2><ul><li><strong>Accounts and authentication</strong>: the frontend sends the OAuth2 authorisation code to the backend, and an identity <strong>provider</strong> exchanges it for a token and a user id (<code>lib/cadet/auth/provider.ex</code>). The providers are ADFS, GitHub and OpenID Connect, the last with claim extractors for Auth0, Cognito, Google, MIT, MIT CSAIL and NUS Entra ID (<code>lib/cadet/auth/providers</code>). Sessions use Guardian tokens.</li><li><strong>Courses and assessments</strong>: courses, assessment configurations, assessments, questions, answers and submissions (<code>lib/cadet/courses</code>, <code>lib/cadet/assessments</code>). An assessment is created in the admin interface or <strong>uploaded as an XML file</strong> (<code>Cadet.Updater.XMLParser</code>, called from the admin assessments controller); the XML format is the one used by the CS1101S assessment repository.</li><li><strong>Grading</strong>: when a submission is made, the backend queues autograding jobs; see <a href="./grader">Grader</a> and <a href="./run-and-submission">A run and a submission</a>. Staff then grade manually in the frontend&#39;s grading screens.</li><li><strong>Other features</strong>: notifications, the leaderboard and incentives (achievements), stories, teams, the AI chat assistants and generated comments (<code>lib/cadet/chatbot</code>, <code>lib/cadet/ai_comments</code>), and registration of remote-execution devices (<code>lib/cadet/devices</code>, with MQTT for EV3 robots).</li><li><strong>The API</strong>: Phoenix controllers under <code>lib/cadet_web</code>, with a Swagger description served at <code>/swagger</code> in development.</li></ul><h2 id="background-jobs" tabindex="-1">Background jobs <a class="header-anchor" href="#background-jobs" aria-label="Permalink to “Background jobs”">​</a></h2><p>Oban runs the jobs, in queues with these limits: <code>default</code> 10, <code>notifications</code> 1, <code>autograder</code> 20 and <code>autograder_results</code> 5 (<code>config/config.exs</code>). Autograding uses two workers: <code>Cadet.Autograder.LambdaWorker</code> invokes the grader and <code>Cadet.Autograder.ResultStoreWorker</code> writes the results to the database (it has a queue of its own, with lower concurrency, because grading takes much longer than the database write). A Quantum cron job (<code>config/config.exs</code>, daily at 00:01) closes and grades the assessments that were due the day before.</p><h2 id="where-to-read-more" tabindex="-1">Where to read more <a class="header-anchor" href="#where-to-read-more" aria-label="Permalink to “Where to read more”">​</a></h2><p>The README (setup with PostgreSQL, secrets, MQTT for remote execution), <code>deployment/</code> for how it is run (see <a href="./deployment">Deployment</a>), and the database schema picture <code>schema.png</code> at the root of the repository.</p>',8)])])}const g=a(r,[["render",n]]);export{m as __pageData,g as default};
